<script setup lang="ts">
import { computed, ref } from 'vue'
const page=ref('Dashboard'), query=ref(''), period=ref('Last 30 days'), selected=ref('Water leak · Unit 204'), contractor=ref(''), jobStatus=ref('Assigned'), notice=ref(''), message=ref(''), modal=ref<HTMLDialogElement|null>(null), modalKind=ref('Assign job'), newTitle=ref(''), priority=ref('Normal')
const requests=ref([{title:'Water leak · Unit 204',detail:'Leaking kitchen sink · reported 24 min ago',status:'Urgent'},{title:'No heat · Unit 110',detail:'Radiator inspection · reported 1 hour ago',status:'Assigned'},{title:'Sticky lock · Unit 305',detail:'Front door access · reported 3 hours ago',status:'Waiting'}])
const contractors=[{name:"Milo's Plumbing",trade:'Plumbing',price:480,eta:'18 min',rating:'96%',load:67},{name:'Northline Heating',trade:'Heating',price:520,eta:'42 min',rating:'92%',load:62},{name:'Arden Electric',trade:'Electrical',price:460,eta:'1.4 days',rating:'94%',load:80}]
const filtered=computed(()=>requests.value.filter(r=>`${r.title} ${r.detail}`.toLowerCase().includes(query.value.toLowerCase())))
const chat=ref([{text:'The leak is contained and parts are on the way.',sent:false},{text:'Thanks. Keep the tenant updated, please.',sent:true}])
function detail(title:string){selected.value=title;page.value='Request detail'}
function assign(name:string){contractor.value=name;modalKind.value='Send job';modal.value?.showModal()}
function confirm(){if(modalKind.value==='New request'){if(!newTitle.value.trim())return;requests.value.unshift({title:newTitle.value,detail:'Created in local demo · just now',status:priority.value});notice.value='Demo request added';newTitle.value=''}else if(modalKind.value==='Approve extra'){notice.value='$200 extra approved in this demo. No money moved.';jobStatus.value='In progress'}else{jobStatus.value='Assigned';page.value='Live job';notice.value=`Job sent to ${contractor.value} in this local demo.`}modal.value?.close()}
function send(){if(!message.value.trim())return;chat.value.push({text:message.value,sent:true});message.value=''}
</script>
<template>
